// Setting definitions for the generic settings renderer.
//
// legacy-schema.json is generated by scripts/extract-schema.mjs from the old
// jQuery templates, so ids, option values and save routing stay byte-for-byte
// compatible with what the Python side reads and writes.
import { isMac, isWindows } from "@/lib/platform"

import raw from "./legacy-schema.json"

export type OptionDef =
  | string
  | number
  | {
      label?: string
      value?: string | number
      image?: string
      types?: string[]
      first_type?: string
    }

export type SettingType = {
  name:
    | "checkbox"
    | "dropdown"
    | "textbox"
    | "button"
    | "keybind"
    | "multicheck"
    | "draglist"
    | "separator"
    | "textbox_with_button"
  data?: OptionDef[]
  triggerFunction?: string
  length?: number
  multiple?: boolean
  maxSelections?: number
  inputType?: "string" | "int" | "float"
  inputLimit?: number
  text?: string
  variant?: string
  inputId?: string
  buttonId?: string
  buttonText?: string
  buttonFunction?: string
  inputOnchange?: string
  inputWidth?: number
}

export type SettingDef = {
  id: string
  title: string
  desc: string
  type: SettingType
}

export type SectionDef = {
  tab: string
  panel: string
  title: string
  desc: string
  /** Only shown on this OS (e.g. the Windows game overlay); everywhere when missing. */
  platform?: "windows" | "mac"
  settings: SettingDef[]
}

const onThisPlatform = (s: SectionDef) => !s.platform || (s.platform === "windows" ? isWindows : isMac)

export const sections = (raw as SectionDef[]).filter(onThisPlatform)

/** Sections for one legacy tab, optionally narrowed to a sub-panel (e.g. "kill-boss-tab"). */
export function sectionsFor(tab: string, panel?: string) {
  return sections.filter((s) => s.tab === tab && (panel === undefined || s.panel === panel))
}

export type SaveTarget = "profile" | "general" | "field" | "custom"

/** How a setting is persisted, derived from the legacy onchange handler. */
export function saveTargetOf(setting: SettingDef): SaveTarget {
  const trigger = setting.type.triggerFunction ?? setting.type.inputOnchange ?? ""
  if (trigger.includes("saveSetting(this, 'profile')")) return "profile"
  if (trigger.includes("saveSetting(this, 'general')")) return "general"
  if (/saveField|loadAndSaveField|updateFieldEnable/.test(trigger)) return "field"
  return "custom"
}

/** Strip tags/emoji and lowercase, matching how the legacy dropdowns derived option values. */
export function normalizeOptionValue(value: string | number): string | number {
  if (typeof value !== "string") return value
  let v = value.replace(/<[^>]*>/g, "")
  try {
    v = v.replace(/[^\p{L}\p{N}\p{P}\p{Z}^$\n]/gu, "")
  } catch {
    v = v.replace(/[^\w\s\-.,]/g, "")
  }
  return v.trim().toLowerCase()
}

export type NormalizedOption = {
  value: string | number
  label: string
  image?: string
  badge?: string
}

export function normalizeOptions(data: OptionDef[] = []): NormalizedOption[] {
  return data.map((opt) => {
    if (opt !== null && typeof opt === "object") {
      const value = opt.value ?? opt.label ?? ""
      return {
        value: normalizeOptionValue(value),
        label: String(opt.label ?? opt.value ?? ""),
        image: opt.image,
        badge: opt.types?.length ? opt.types.map((t) => t[0].toUpperCase()).join("/") : undefined,
      }
    }
    return { value: normalizeOptionValue(opt), label: String(opt) }
  })
}

/** Loose equality used by the legacy UI ("5" == 5). */
export function sameValue(a: unknown, b: unknown) {
  // eslint-disable-next-line eqeqeq
  return a == b || String(a).toLowerCase() === String(b).toLowerCase()
}
